function spaces(army){return army.reduce(function(n,v,i){return n+v*U[i].space;},0);}
Engine.prototype.migrateBase=function(){var d=this.d;if(!d.mapSize){d.buildings.forEach(function(b){b.x+=5;b.y+=5;});d.mapSize=20;}
 d.garrison=U.map(function(_,i){return Array.isArray(d.garrison)&&Number.isInteger(d.garrison[i])&&d.garrison[i]>=0?Math.min(80,d.garrison[i]):0;});
 if(!Number.isFinite(d.crystals))d.crystals=0;if(!d.research)d.research={weapon:0,armor:0};if(!Array.isArray(d.receipts))d.receipts=[];
};
Engine.prototype.crystalCapacity=function(){return this.d.onlineCrystal?this.d.onlineCrystal.capacity:200+this.d.buildings.filter(function(b){return b.type==='crystalstore'&&active(b);}).reduce(function(n,b){return n+800*b.lv;},0);};
Engine.prototype.crystalRate=function(){return this.d.onlineCrystal?this.d.onlineCrystal.rate:120*this.level('crystalplant');};
Engine.prototype.garrisonCapacity=function(){var lv=this.level('garrison');return lv?5+lv*5:0;};
Engine.prototype.station=function(i,delta){this.sync();if(!U[i]||Math.abs(delta)!==1)return'เลือกทหารให้ถูกต้อง';if(delta>0){if(!this.d.army[i])return'ไม่มีทหารชนิดนี้';if(spaces(this.d.garrison)+U[i].space>this.garrisonCapacity())return'กองบัญชาการป้องกันเต็ม';this.d.army[i]--;this.d.garrison[i]++;}else{if(!this.d.garrison[i])return'ไม่มีทหารประจำการ';this.d.garrison[i]--;this.d.army[i]++;}this.save();return'';};
Engine.prototype.buyResearch=function(kind){if(!['weapon','armor'].includes(kind))return'ไม่พบงานวิจัย';if(this.d.onlineCrystal)return'วิจัยผ่านศูนย์ผลึกออนไลน์';var lv=this.d.research[kind];if(lv>=5)return'วิจัยสูงสุดแล้ว';if(this.level('tech')<lv+1)return'อัปเกรดศูนย์วิจัยก่อน';var cost=50*(lv+1);if(this.d.crystals<cost)return'ผลึกไม่พอ';this.d.crystals-=cost;this.d.research[kind]++;this.save();return'';};
// Damage affects gameplay and preserves wrecks. Knockback checks every small step against solids.
function hit(scene,target,damage,source,weapon){if(target.hp<=0)return;if(scene.buildings.some(function(b){return b.type==='shield'&&b.hp>0&&b!==target&&dist(b,target)<=3.5;}))damage*=.75;target.hp=Math.max(0,target.hp-damage);target.hit=.25;
 var blast=['cannon','grenade','missile','bomb'].indexOf(weapon)>=0;
 if(!target.type){target.hop=blast?.55:.12;if(blast){var dx=target.x-source.x,dy=target.y-source.y,len=Math.hypot(dx,dy)||1,weight=target.kind===undefined?1:U[target.kind].space,push=1.1/Math.sqrt(weight);for(var n=0;n<6;n++){var x=target.x+dx/len*push/6,y=target.y+dy/len*push/6;if(x<0||y<0||x>(scene.mapSize||12)-1||y>(scene.mapSize||12)-1||scene.buildings.some(function(b){return b.hp>0&&Math.abs(x-b.x)<.65&&Math.abs(y-b.y)<.65;}))break;target.x=x;target.y=y;}target.route=[];}if(weapon==='tesla'||weapon==='shock')target.stun=.35;}
 scene.fx.push({x:target.x,y:target.y,tx:target.x,ty:target.y,weapon:'impact',life:blast?.6:.22,maxLife:blast?.6:.22,color:blast?'#ffb568':'#c4f6ff',radius:blast?24:8});
 if(target.hp===0){target.dead=1.4;target.destroyedAt=Date.now();scene.fx.push({x:target.x,y:target.y,tx:target.x,ty:target.y,weapon:'impact',life:.8,maxLife:.8,color:'#ffba70',radius:target.type?36:20});}
}
function ageCombat(scene,dt){scene.buildings.concat(scene.troops||[],scene.guards||[],scene.enemies||[],scene.defenders||[]).forEach(function(o){o.hit=Math.max(0,(o.hit||0)-dt);o.hop=Math.max(0,(o.hop||0)-dt);o.stun=Math.max(0,(o.stun||0)-dt);if(o.dead)o.dead=Math.max(0,o.dead-dt);});scene.fx=scene.fx.slice(-70);}
function makeDefenders(e){var b=e.d.buildings.find(function(b){return b.type==='garrison'&&active(b);});if(!b)return[];var out=[];e.d.garrison.forEach(function(count,kind){for(var j=0;j<count;j++){var u=U[kind],hp=u.hp*(1+e.d.research.armor*.1);out.push({id:out.length+1,kind:kind,x:b.x,y:b.y,hp:hp,max:hp,cool:0,route:[]});}});return out;}
function defenderTick(e,d,dt){var alive=d.buildings.filter(function(b){return b.hp>0;});(d.defenders||[]).forEach(function(t){if(t.hp<=0||t.stun>0)return;var u=U[t.kind];t.cool-=dt;var targets=u.weapon==='heal'?d.defenders.filter(function(v){return v!==t&&v.hp>0&&v.hp<v.max;}):d.enemies.filter(function(v){return v.hp>0;});targets.sort(function(a,b){return dist(t,a)-dist(t,b);});var target=targets[0];if(!target)return;var dd=dist(t,target);if(dd<=u.range){if(t.cool<=0){if(u.weapon==='heal')target.hp=Math.min(target.max,target.hp+u.damage);else{hit(d,target,u.damage*(1+e.d.research.weapon*.1),t,u.weapon);if(u.splash)d.enemies.forEach(function(v){if(v!==target&&v.hp>0&&dist(v,target)<=u.splash)hit(d,v,u.damage*.5,t,u.weapon);});}d.fx.push(weaponFX(t,target,u.weapon));t.cool=u.rate;}}else{t.pathAge=(t.pathAge||0)-dt;if(t.pathAge<=0||!t.route.length){t.route=u.air?[{x:target.x,y:target.y}]:route(t,target,alive,u.range,21)||[];t.pathAge=.6;}var p=t.route[0];if(p){var len=dist(t,p),step=Math.min(len,u.speed*dt);if(len){t.x+=(p.x-t.x)/len*step;t.y+=(p.y-t.y)/len*step;if(step>=len)t.route.shift();}}}});}

function active(b){return !b.constructing;}
function duration(seconds){seconds=Math.max(0,Math.ceil(seconds));return Math.floor(seconds/60)+':'+('0'+seconds%60).slice(-2);}
function initial(now){return{version:1,gems:30,checkin:{day:-1,streak:0},rewardIds:[],gold:900,power:500,stage:1,stars:{},army:[8,1,1,0,0,0,0,0,0],queue:[],last:now,buildings:[{id:1,type:'hq',x:5,y:5,lv:1},{id:2,type:'barracks',x:3,y:5,lv:1},{id:3,type:'mine',x:5,y:3,lv:1},{id:4,type:'reactor',x:7,y:5,lv:1},{id:5,type:'gun',x:5,y:7,lv:1},{id:6,type:'camp',x:7,y:7,lv:1}],next:7};}
function Engine(storage,now){this.storage=storage;this.now=now||Date.now;this.d=initial(this.now());try{var d=JSON.parse(storage.getItem('novaRTS1'));if(d&&d.version===1&&Array.isArray(d.buildings)&&d.buildings.some(function(b){return b.type==='hq';})&&d.buildings.every(function(b){return !!B[b.type]&&Number.isFinite(b.x)&&Number.isFinite(b.y)&&b.lv>=1&&b.lv<=15;})&&Array.isArray(d.army)&&d.army.length>=4&&d.army.length<=U.length&&d.army.every(function(n){return Number.isFinite(n)&&n>=0;})&&Array.isArray(d.queue)&&Number.isFinite(d.gold)&&Number.isFinite(d.power)){this.d=d;}}catch(e){}while(this.d.army.length<U.length)this.d.army.push(0);if(!Number.isFinite(this.d.gems))this.d.gems=30;if(!this.d.checkin)this.d.checkin={day:-1,streak:0};if(!Array.isArray(this.d.rewardIds))this.d.rewardIds=[];this.raid=null;this.defense=null;if(!this.d.tasks)this.d.tasks={day:-1,build:0,train:0,win:0,defend:0,claimed:[]};if(!this.d.defenseLevel)this.d.defenseLevel=1;this.migrateBase();this.sync();}
Engine.prototype.save=function(){try{this.storage.setItem('novaRTS1',JSON.stringify(this.d));this.saveFailed=false;return true;}catch(e){this.saveFailed=true;return false;}};
Engine.prototype.hq=function(){return this.d.buildings.find(function(b){return b.type==='hq';}).lv;};
Engine.prototype.capacity=function(){return 12+this.d.buildings.filter(function(b){return b.type==='camp'&&active(b);}).reduce(function(s,b){return s+8*b.lv;},0);};
Engine.prototype.housing=function(){return this.d.army.reduce(function(s,n,i){return s+n*U[i].space;},0)+this.d.queue.reduce(function(s,q){return s+U[q.kind].space;},0)+spaces(this.d.garrison||[])+(this.d.pendingCrystal&&this.d.pendingCrystal.kind==='unit'?U[this.d.pendingCrystal.index].space:0);};
// Production is integrated across completion boundaries; full stores discard production, never bank it.
Engine.prototype.resourceCapacity=function(kind){return 2000+1000*(this.hq()-1)+this.d.buildings.filter(function(b){return b.type==='storage'&&active(b);}).reduce(function(n,b){return n+2000*b.lv;},0)+this.d.buildings.filter(function(b){return b.type===(kind==='power'?'powerstore':'goldstore')&&active(b);}).reduce(function(n,b){return n+2000*b.lv;},0);};
Engine.prototype.deposit=function(kind,amount){var accepted=Math.min(Math.max(0,amount),Math.max(0,(kind==='crystals'?this.crystalCapacity():this.resourceCapacity(kind))-this.d[kind]));this.d[kind]+=accepted;return accepted;};
Engine.prototype.produceUntil=function(n){var self=this;this.d.buildings.forEach(function(b){if(b.type!=='mine'&&b.type!=='reactor'&&b.type!=='crystalplant')return;if(b.type==='crystalplant'&&self.d.onlineCrystal)return;var from=Number.isFinite(b.collected)?b.collected:self.d.last;if(!Number.isFinite(from))from=n;if(n<=from)return;if(!active(b)){b.collected=n;return;}var kind=b.type==='mine'?'gold':b.type==='crystalplant'?'crystals':'power',rate=b.type==='crystalplant'?b.lv/30:.6*b.lv,amount=Math.floor((n-from)/1000*rate+0.000001);if(amount>0){self.deposit(kind,amount);b.collected=from+amount/rate*1000;}if(self.d[kind]>=(kind==='crystals'?self.crystalCapacity():self.resourceCapacity(kind)))b.collected=n;});};
Engine.prototype.sync=function(){var n=this.now(),self=this,events=this.d.buildings.filter(function(b){return b.until&&b.until<=n;}).sort(function(a,b){return a.until-b.until;});events.forEach(function(b){self.produceUntil(b.until);if(b.constructing){b.collected=b.until;delete b.constructing;}else b.lv++;delete b.until;delete b.started;self.progress('build');});this.produceUntil(n);this.d.queue=this.d.queue.filter(function(q){if(q.until>n)return true;self.d.army[q.kind]++;self.progress('train');return false;});this.save();};
Engine.prototype.stored=function(){return 0;};
Engine.prototype.collect=function(){var g=this.d.gold,p=this.d.power;this.sync();return{gold:this.d.gold-g,power:this.d.power-p};};
Engine.prototype.progress=function(kind){if(this.d.tasks.day!==this.day())this.d.tasks={day:this.day(),build:0,train:0,win:0,defend:0,claimed:[]};this.d.tasks[kind]=(this.d.tasks[kind]||0)+1;};
Engine.prototype.claimTask=function(kind){var goals={build:2,train:5,win:2,defend:1};if(this.d.tasks.day!==this.day()||!goals[kind]||this.d.tasks[kind]<goals[kind]||this.d.tasks.claimed.indexOf(kind)>=0)return false;this.d.tasks.claimed.push(kind);this.d.gems+=5;this.save();return true;};
Engine.prototype.wallGroup=function(id,mode){var b=this.d.buildings.find(function(b){return b.id===id&&b.type==='wall';});if(!b)return[];var walls=this.d.buildings.filter(function(w){return w.type==='wall';});if(mode==='one')return[b];var group=[b],seen={};seen[b.id]=true;for(var i=0;i<group.length;i++)walls.forEach(function(w){if(seen[w.id]||Math.abs(w.x-group[i].x)+Math.abs(w.y-group[i].y)!==1)return;if(mode==='x'&&w.y!==b.y||mode==='y'&&w.x!==b.x)return;seen[w.id]=true;group.push(w);});return group;};
Engine.prototype.wallQuote=function(id,mode){var self=this,items=this.wallGroup(id,mode).filter(function(b){return !b.until&&b.lv<15&&b.lv<self.hq();});return{ids:items.map(function(b){return b.id;}),gold:items.reduce(function(n,b){return n+self.upgradeCost(b).gold;},0),power:items.reduce(function(n,b){return n+self.upgradeCost(b).power;},0),crystals:items.reduce(function(n,b){return n+self.upgradeCost(b).crystals;},0)};};
Engine.prototype.upgradeWalls=function(id,mode,quote){this.sync();if(this.d.pendingCrystal&&this.d.pendingCrystal.kind!=='unit')return'กำลังยืนยันผลึกสำหรับงานก่อสร้าง';var q=this.wallQuote(id,mode);if(!q.ids.length)return'ไม่มีกำแพงที่อัปเกรดได้';if(JSON.stringify(q)!==quote)return'รายการเปลี่ยน กรุณาเลือกใหม่';if(this.d.buildings.some(function(b){return b.until;}))return'ช่างกำลังทำงาน';if(this.d.gold<q.gold||this.d.power<q.power||this.d.crystals<q.crystals)return'ทรัพยากรไม่พอ';if(q.crystals&&this.d.onlineCrystal)return'อัปเกรดกำแพงด้วยผลึกออนไลน์ผ่านเซิร์ฟเวอร์';this.d.crystals-=q.crystals;this.d.gold-=q.gold;this.d.power-=q.power;var self=this;this.d.buildings.forEach(function(b){if(q.ids.indexOf(b.id)>=0){b.lv++;self.progress('build');}});this.save();return'';};
Engine.prototype.speedTraining=function(quoted){this.sync();if(!this.d.queue.length)return'คิวฝึกเสร็จแล้ว';var cost=Math.ceil((Math.max.apply(null,this.d.queue.map(function(q){return q.until;}))-this.now())/30000);if(cost>quoted)return'ราคาเปลี่ยน กรุณายืนยันใหม่';if(this.d.gems<cost)return'เพชรไม่พอ';this.d.gems-=cost;var self=this;this.d.queue.forEach(function(q){q.until=self.now();});this.sync();return'';};
Engine.prototype.empty=function(x,y,ignore){return x>=1&&y>=1&&x<=20&&y<=20&&!this.d.buildings.some(function(b){return b.id!==ignore&&b.x===x&&b.y===y;});};
Engine.prototype.build=function(type,x,y){this.sync();if(this.d.pendingCrystal&&this.d.pendingCrystal.kind!=='unit')return'กำลังยืนยันผลึกสำหรับงานก่อสร้าง';var b=B[type];if(!b||type==='hq'||!this.empty(x,y))return'วางตรงนี้ไม่ได้';if(this.d.buildings.filter(function(a){return a.type===type;}).length>=b.cap)return'ครบจำนวนอาคารชนิดนี้แล้ว';if(this.hq()<(b.require||((type==='factory'||type==='tesla')?2:1)))return'ต้องมีศูนย์บัญชาการระดับ '+(b.require||2);if(this.d.buildings.some(function(a){return a.until;}))return'ช่างกำลังทำงาน รอหรือใช้เพชรเร่งเวลา';if(this.d.gold<b.cost||this.d.power<b.power)return'ทรัพยากรไม่พอ';this.d.gold-=b.cost;this.d.power-=b.power;this.d.buildings.push({id:this.d.next++,type:type,x:x,y:y,lv:1,collected:this.now(),constructing:true,started:this.now(),until:this.now()+(b.time||(type==='wall'?3:15))*1000});this.save();return'';};
